@namespace ghidra.features.@base.quickfix;






using docking.widgets.table;
using generic.theme;
using ghidra.docking.settings;
using ghidra.util.exception;
using ghidra.util.table.column;
using resources;

/**
 * Renderer for the {@link QuickFixStatus} column
 */
public class QuickFixStatusRenderer : AbstractGhidraColumnRenderer<QuickFixStatus> {

	private static readonly Icon DONE_ICON = new GIcon("icon.base.plugin.quickfix.done");
	private static readonly Icon ERROR_ICON = Icons.ERROR_ICON;
	private static readonly Icon WARNING_ICON = Icons.WARNING_ICON;
	private static readonly Icon DELETE_ICON = Icons.DELETE_ICON;

	/* @Override */
	public Component getTableCellRendererComponent(GTableCellRenderingData data) {

		JLabel renderer = (JLabel) base.getTableCellRendererComponent(data);
		QuickFixStatus status = (QuickFixStatus) data.getValue();

		Icon icon = getIcon(status);
		renderer.setIcon(icon);
		renderer.setText("");
		QuickFix rowObject = (QuickFix) data.getRowObject();
		renderer.setToolTipText(rowObject.getStatusMessage());

		return renderer;
	}

	private Icon getIcon(QuickFixStatus status) {
		switch (status) {
			case DONE:
				return DONE_ICON;
			case WARNING:
			case CHANGED:
				return WARNING_ICON;
			case ERROR:
				return ERROR_ICON;
			case DELETED:
				return DELETE_ICON;
			case NONE:
				return null;
			default:
				throw new AssertException("Unexpected QuickFix status: " + status);
		}
	}

	/* @Override */
	public string getFilterString(QuickFixStatus t, Settings settings) {
		return t.toString();
	}

}
